import numpy as np
from openai import OpenAI

oai = OpenAI()

class SemanticCache:
    """Cache LLM responses for semantically similar queries."""
    def __init__(self, threshold: float = 0.95):
        self.threshold = threshold
        self.entries = []  # List of {embedding, response}

    def _embed(self, text: str) -> np.ndarray:
        vec = oai.embeddings.create(input=text, model="text-embedding-3-small").data[0].embedding
        return np.array(vec)

    def _cosine(self, a: np.ndarray, b: np.ndarray) -> float:
        return float(np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b)))

    def get(self, query: str):
        q_emb = self._embed(query)
        for entry in self.entries:
            sim = self._cosine(q_emb, entry["embedding"])
            if sim >= self.threshold:
                return entry["response"]  # Cache hit!
        return None

    def set(self, query: str, response: str):
        self.entries.append({"embedding": self._embed(query), "response": response})

cache = SemanticCache(threshold=0.95)

